WITH base AS (SELECT * FROM shipments WHERE status <> 'IN_TRANSIT'), Summary AS (SELECT CASE WHEN cost >= 97 THEN 'high' WHEN cost >= 32 THEN 'mid' ELSE 'low' END AS cost_bucket, QUARTER(delivered_date) AS delivered_quarter, MIN(cost) AS min_cost, COUNT(*) AS row_count FROM base GROUP BY CASE WHEN cost >= 97 THEN 'high' WHEN cost >= 32 THEN 'mid' ELSE 'low' END, QUARTER(delivered_date)) SELECT * FROM Summary
